#include <stdio.h>
#include <stdlib.h>

// Function to get value from array at given index
int getValueFromArray(int arr[], int size, int index) {
    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    int size, index;

    // Read the size of the array from standard input
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    if (size <= 0) {
        fprintf(stderr, "Invalid size. Please enter a positive integer.\n");
        return -1;
    }

    // Allocate memory for the array
    int* arr = (int*)malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    // Read elements of the array from standard input
    printf("Enter %d elements for the array:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Read the index from standard input
    printf("Enter the index to retrieve: ");
    scanf("%d", &index);

    // Call getValueFromArray and get the result
    int result = getValueFromArray(arr, size, index);

    // Free allocated memory
    free(arr);

    // Return the result as the exit code
    return result;
}
```

### Explanation:
