    // Allocate memory for the person structure
    struct person* p = (struct person*)malloc(sizeof(struct person));

    if (p == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize the members of the struct
    strcpy(p->name, name);
    p->age = age;

    return p;
