```c
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>

int main() {
    const char *filename = "important_config";
    const char *content = "important_config";
    int fd;
    ssize_t bytes_written;

    // Open or create the file with write-only permission (O_WRONLY) and create flag (O_CREAT)
    // Also set permissions to read and write for the owner (S_IRUSR | S_IWUSR)
    fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);

    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    // Write the content to the file
    bytes_written = write(fd, content, sizeof(content));

    if (bytes_written == -1) {
        perror("Error writing to file");
        close(fd);
        return 1;
    }

    printf("Successfully wrote %zd bytes to %s\n", bytes_written, filename);

    // Close the file
    close(fd);

    return 0;
}
```

### Explanation:
