    const char *data = "important_config";
    int fd;
    ssize_t bytes_written;

    // Open the file for reading and writing, create if it doesn't exist
    fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
