#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void trim_trailing_whitespace(char *str) {
    size_t len = strlen(str);
    while (len > 0 && isspace((unsigned char)str[len - 1])) {
        str[--len] = '\0';
    }
}

void trim_newlines(char *str) {
    size_t len = strlen(str);
    for (size_t i = len; i > 0; --i) {
        if (str[i - 1] == '\n') {
            str[i - 1] = '\0';
        } else {
            break;
        }
    }
}

int main(int argc, char *argv[]) {
    // Check if exactly one argument is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <string>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Ensure the first argument is a string
    char *input_string = argv[1];

    // Trim trailing whitespace
    trim_trailing_whitespace(input_string);

    // Trim newlines
    trim_newlines(input_string);

    // Null-terminate the string (just to be safe)
    input_string[strcspn(input_string, "\0")] = '\0';

    // Output the trimmed string
    printf("Trimmed String: %s\n", input_string);

    return EXIT_SUCCESS;
}
```

### Explanation:
