    // Open a sample request and response files for demonstration purposes
    FILE *request = fopen("request.txt", "r");
    if (request == NULL) {
        perror("Error opening request file");
        return EXIT_FAILURE;
    }

    FILE *response = fopen("response.txt", "w");
    if (response == NULL) {
        perror("Error opening response file");
        fclose(request);
        return EXIT_FAILURE;
    }

    // Call the function with the sample files
    http_hello_page(request, response);

    // Close the files
    fclose(request);
    fclose(response);

    return EXIT_SUCCESS;
}
```

### Explanation:
